# Actual second sketches. Files are neutral synthetic learner attachments.
def drawing(name,origin=0,direction=1,length=2,head=True,assignment=True,arrow_label=None,unit='m/s',floating=False,large=False):
 unitpx=40 if large else 120;xa=120 if large else 290;xb=xa+3*unitpx;y=110
 im=Image.new('RGB',(1100,280),'white');dd=ImageDraw.Draw(im)
 dd.text((25,15),'II',font=font(28),fill='#213344')
 dd.text((110,15),'x : 1 cm ≙ 1 m',font=font(26),fill='#213344')
 dd.text((520,15),'v : 1 cm ≙ 3 '+unit,font=font(26),fill='#126587')
 start=xa+origin*unitpx+(0.4*unitpx if floating else 0);tip=start+direction*length*unitpx
 dd.line((start,y,tip,y),fill='#126587',width=5)
 if head:dd.polygon([(tip,y),(tip-direction*18,y-9),(tip-direction*18,y+9)],fill='#126587')
 dd.text(((start+tip)/2-25,y-38),arrow_label or ('v_A' if assignment else 'v'),font=font(26),fill='#126587')
 for x,label in [(xa,'A'),(xb,'B')]:dd.ellipse((x-5,y-5,x+5,y+5),fill='#213344');dd.text((x-9,y+18),label,font=font(26),fill='#213344')
 ry=200;dd.line((xa,ry,xb,ry),fill='#596a77',width=2)
 for k in range(7):px=xa+k*unitpx/2;dd.line((px,ry-6,px,ry+6),fill='#596a77',width=2)
 for k in range(4):dd.text((xa+k*unitpx-6,ry+14),str(k)+(' cm' if k==3 else ''),font=font(20),fill='#213344')
 im.save(BASE/'blind/drawings'/f'{name}.png')
drawing('R01');drawing('R02',head=False);drawing('R03',length=2.5);drawing('R04',unit='m')
drawing('R05',origin=3,arrow_label='v_B');drawing('R06',direction=-1);drawing('R07',length=18,large=True)
drawing('R08',assignment=False,floating=True);drawing('R09',head=False,assignment=False);drawing('R10',length=1)

