 sid=f'S{n:02d}';de='\n\n'.join(b[0] for b in blocks);en='\n\n'.join(b[1] for b in blocks)
 cases.append({'id':sid,'responseDe':de,'responseEn':en,'drawingPaths':[f'drawings/{draw}.png'] if draw else []})
 pp=dict(zip('ABCD',points));expect.append({'id':sid,'expectedPointsDe':pp,'expectedPointsEn':pp,'expectedTotal':sum(points),'expectedPass':sum(points)>=13.5,'purpose':purpose,'rationale':rationale})
