add(9,[A,B,(C_DE.replace('in meiner tatsächlichen Zeichnung','in meiner Beschreibung')+' Eine Zeichnung fertige ich nicht an.',C_EN.replace('in my actual drawing','in my description')+' I do not make a drawing.'),D],[2,2,2,4],'nur Text','A1Zuordnung+1Begründung;B1Lesen+1Boden;C1,5Ablesen+0,5Rechnen; keine tatsächliche Zeichnung/Legenden.10.',draw=None)
add(10,[A,B,(C_DE+' In meiner Geschwindigkeitslegende steht nur versehentlich m statt m/s; meine Rechnung und Größenunterscheidung bleiben wie oben.',C_EN+' In my own legend I accidentally write m instead of m/s; my calculation and distinction between quantities remain as above.'),D],[4,4,3.5,4],'Legendenformfehler','C einmal−0,5; kein weiterer Verlust der Legendenpunkte.',draw='R04')
add(11,[A,(B_DE+' Den einzelnen Pfeilkopf habe ich beim Zeichnen vergessen.',B_EN+' I forgot the one arrowhead while drawing.'),C,D],[4,3.5,4,4],'fehlender Kopf mit unabhängigem Kernbeleg','Explizite rechte Richtung und passender Verlauf belegen Zeichenfehler; genau−0,5 inB.',draw='R02')
add(12,[A,('Der Bezugsrahmen ist der ruhende Boden. Zur Richtung schreibe ich nichts; meine beigefügte Linie hat keinen Pfeilkopf.','The reference frame is the stationary ground. I write nothing about direction; my attached line has no arrowhead.'),C,D],[4,1,4,4],'fehlender Kopf ohne Kernbeleg','Kein unabhängiger richtiger Richtungssatz; B1 nurBezugsrahmen, kein zusätzlicher−0,5.',draw='R09')
add(13,[A,B,(C_DE.replace('= 2 cm','= 2,5 cm')+' 6/3 habe ich einmal falsch ausgerechnet und den Wert unverändert in die Zeichnung übernommen.',C_EN.replace('= 2 cm','= 2.5 cm')+' I miscalculated 6/3 once and copied that value into my drawing.'),(D_DE.replace('2 cm statt','2,5 cm statt'),D_EN.replace('2 cm long','2.5 cm long'))],[4,4,3.5,4],'sauberer lokaler Folgefehler','Ein Ursprung inC; D folgert aus2,5<3 weiterhin richtig keinen Kontakt und keine Lageänderung.',draw='R03')
add(14,[('Die Geschwindigkeit gehört B, weil die Pfeilspitze dort endet. Daher beginne ich meinen neuen Pfeil absichtlich an B. Diese Regel halte ich aufrecht.','The velocity belongs to B because the arrow tip ends there. So I deliberately start my new arrow at B. I maintain that rule.'),B,C,('Meine neue Spitze liegt 2 cm rechts von B, also nicht mehr auf B. Eine Geschwindigkeitsspitze bezeichnet dennoch keinen Ort ihres Trägers und keinen Kontakt: ihre Lage folgt dem eigenen Maßstab in m/s, keiner Ortsstrecke in m. Die tatsächlichen Körperorte und Geschwindigkeiten ändern sich durch den Maßstab nicht.','My new tip is 2 cm to the right of B, so no longer at B. A velocity tip nevertheless indicates no position of its carrier and no contact: its location follows the separate m/s scale, not a position distance in m. Actual object positions and velocities do not change with the scale.')],[0,4,4,4],'Trägerfehlvorstellung mit konsistenter Folge','NurA0; B/C unabhängig und D deutet die eigeneverschobeneSpitze konsistent.',draw='R05')
add(15,[A,('Ich lese die Geschwindigkeit relativ zum Boden nach links. Nach meiner Regel zeigt ein rechts gerichteter Geschwindigkeitspfeil Bewegung nach links; daran halte ich fest. Mein II-Pfeil zeigt deshalb links.','I read the velocity relative to the ground as leftwards. My rule is that a rightward velocity arrow means motion leftwards; I maintain that rule. My II arrow therefore points left.'),C,('Meine neue Spitze liegt 2 cm links von A und damit nicht auf B. Sie bezeichnet weder einen Ort von A noch Kontakt mit B, denn ihr Ort folgt dem eigenen Geschwindigkeitspfeilmaßstab in m/s, nicht einer Ortsstrecke in m. Körperorte und wirkliche Geschwindigkeit bleiben beim Maßstabswechsel gleich.','My new tip is 2 cm left of A and thus not at B. It indicates neither a position of A nor contact with B, because its location follows the separate velocity-arrow scale in m/s, not a position distance in m. Object positions and actual velocity stay the same under the scale change.')],[4,0,4,4],'Richtungsfehlvorstellung mit konsistenter Folge','B0; C unsigned Länge und D eigeneSpitzenlage korrekt weiterverarbeitet.',draw='R06')
add(16,[A,B,('Aus dem Lineal lese ich 3·2 = 6 m/s. Bei einem neuen Pfeilmaßstab muss ich allgemein multiplizieren, also 6·3 = 18 cm. Diese Maßstabsregel halte ich aufrecht; so zeichne ich II. Beide Skalen sind beschriftet.','The ruler gives 3·2 = 6 m/s. For a new arrow scale I must always multiply, so 6·3 = 18 cm. I maintain this scale rule and draw II that way. Both scales are labelled.'),('Meine Spitze liegt weit hinter B, weil mein Pfeil 18 cm statt des Körperabstands von 3 cm lang ist. Sie ist weder ein Ort von A noch ein Kontaktbeleg: ihre Lage folgt dem eigenen Geschwindigkeitspfeilmaßstab in m/s, keiner Ortsstrecke in m. Körperorte und wirkliche Geschwindigkeit bleiben beim bloßen Maßstabswechsel gleich.','My tip lies far beyond B because my arrow is 18 cm long instead of the object separation of 3 cm. It is neither a position of A nor evidence of contact: its location follows the separate velocity-arrow scale in m/s, not a position distance in m. Object positions and actual velocity stay the same when only the scale changes.')],[4,4,0,4],'Maßstabsfehlvorstellung mit konsistenter Folge','C0 für allgemeinfalscheRegel. D deute18>3 folgerichtig und verwechselt nicht Spitze mitOrt.',draw='R07')
add(17,[A,B,C,('Die Spitze in I beweist, dass A jetzt B berührt. Daran halte ich fest; eine Erklärung mit getrennten Größenräumen lehne ich ab.','The tip in I proves that A touches B now. I maintain that claim and reject an explanation using separate quantity spaces.')],[4,4,4,0],'Kontaktfehlvorstellung','D vollständig0; keine vorangestellte korrekte D-Musterantwort.')
add(18,[A,B,C,('Durch den neuen Pfeilmaßstab wird A wirklich langsamer und verschiebt sich an die neue Spitze. Das ist meine endgültige Deutung.','The new arrow scale makes A actually slower and moves A to the new tip. This is my final interpretation.')],[4,4,4,0],'Skala als physikalische Änderung','D0; konkrete beibehaltene Fehlvorstellung ohne widersprüchliche Referenzblöcke.')
add(19,[A,B,C,('Zuerst dachte ich, A berühre B an der Spitze. Das nehme ich ausdrücklich zurück. '+D_DE,'At first I thought A touched B at the tip. I explicitly retract that. '+D_EN)],[4,4,4,4],'ausdrückliche Rücknahme','Zurückgenommene Behauptung löst den Widerspruch; kompletter richtiger Endstand.')
add(20,[A,B,C],[4,4,4,0],'nur richtige Zahlen und Zeichnung ohne D','Keine Erklärung/Voraussage/Invarianz in Abgabe; Zeichnung2cm erzeugt keine D-Punkte.12.')
